-- Initial schema for the independent bpark project.
CREATE TABLE areas (id smallint PRIMARY KEY, name text NOT NULL UNIQUE, CHECK (id BETWEEN 1 AND 11));
INSERT INTO areas (id, name) VALUES (1, 'מתקני הכושר'), (2, 'בין צמרות'), (3, 'משחק לפעוטות'), (4, 'מצללת מטפסים'), (5, 'רחבת נורדאו'), (6, 'המעיין הפועם'), (7, 'אזור נדנדות'), (8, 'דק הפרלמנט'), (9, 'שביל נגיש'), (10, 'פרגולות הזית והחורשה'), (11, 'חצר כלבים');
CREATE TABLE app_users (auth_user_id text PRIMARY KEY, display_name text NOT NULL, role text NOT NULL CHECK (role IN ('volunteer','coordinator')), enabled boolean NOT NULL DEFAULT true);
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_at timestamptz NOT NULL, title text NOT NULL, summary text NOT NULL DEFAULT '', participants text NOT NULL DEFAULT '', next_visit_focus text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','in_review','approved','published')), created_by text NOT NULL REFERENCES app_users(auth_user_id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz, published_at timestamptz);
CREATE TABLE area_observations (report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, area_id smallint NOT NULL REFERENCES areas(id), work_status text NOT NULL DEFAULT 'not_checked' CHECK (work_status IN ('not_checked','not_started','in_progress','completed','other')), change_since_previous text NOT NULL DEFAULT '', observation text NOT NULL DEFAULT '', interpretation text NOT NULL DEFAULT '', question text NOT NULL DEFAULT '', PRIMARY KEY (report_id, area_id));
CREATE TABLE report_notes (report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, topic text NOT NULL CHECK (topic IN ('entrances','accessibility_transport','infrastructure','summary')), content text NOT NULL DEFAULT '', PRIMARY KEY (report_id, topic));
CREATE TABLE report_photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, area_id smallint REFERENCES areas(id), object_key text NOT NULL UNIQUE, caption text NOT NULL DEFAULT '', photographed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE area_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), area_id smallint NOT NULL REFERENCES areas(id), object_key text NOT NULL UNIQUE, caption text NOT NULL DEFAULT '', source text NOT NULL DEFAULT '');
CREATE TABLE report_approvals (report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, auth_user_id text NOT NULL REFERENCES app_users(auth_user_id), approved_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (report_id, auth_user_id));
